wgsl:
struct Uniforms {
  mvp : mat4x4<f32>,
  normalMatrix : mat3x3<f32>,
  scale : f32,
  lod : f32,
};
@group(0) @binding(0) var<uniform> u : Uniforms;

@group(0) @binding(1) var heightMap : texture_2d<f32>;
@group(0) @binding(2) var heightMapSampler : sampler;
@group(0) @binding(3) var tint : texture_2d<f32>;
@group(0) @binding(4) var tintSampler : sampler;

struct VertexInput {
  @location(0) position : vec3<f32>,
  @location(1) normal : vec3<f32>,
  @location(2) uv : vec2<f32>,
};

struct VertexOutput {
  @builtin(position) position : vec4<f32>,
  @location(0) height : f32,
  @location(1) vUv : vec2<f32>,
};

@vertex
fn vertexMain(in : VertexInput) -> VertexOutput {
  var out : VertexOutput;
  let h = textureSampleLevel(heightMap, heightMapSampler, in.uv, u.lod).x;
  let p = (in.position + (in.normal * (h * u.scale)));
  out.height = h;
  out.vUv = in.uv;
  out.position = (u.mvp * vec4<f32>(p, 1.0));
  return out;
}

@fragment
fn fragmentMain(in : VertexOutput) -> @location(0) vec4<f32> {
  let c = textureSample(tint, tintSampler, in.vUv);
  return vec4<f32>(vec3<f32>((c.x * (0.5 + in.height)), (c.y * (0.5 + in.height)), (c.z * (0.5 + in.height))), 1.0);
}

glslVertex:
attribute vec3 position;
attribute vec3 normal;
attribute vec2 uv;
uniform mat4 mvp;
uniform mat3 normalMatrix;
uniform float scale;
uniform float lod;
uniform highp sampler2D heightMap;
varying float height;
varying vec2 vUv;

void main() {
  float h = texture2DLod(heightMap, uv, lod).x;
  vec3 p = (position + (normal * (h * scale)));
  height = h;
  vUv = uv;
  gl_Position = (mvp * vec4(p, 1.0));
}

glslFragment:
precision mediump float;
uniform mat4 mvp;
uniform mat3 normalMatrix;
uniform float scale;
uniform float lod;
varying float height;
varying vec2 vUv;
uniform sampler2D heightMap;
uniform sampler2D tint;

void main() {
  vec4 c = texture2D(tint, vUv);
  gl_FragColor = vec4(vec3((c.x * (0.5 + height)), (c.y * (0.5 + height)), (c.z * (0.5 + height))), 1.0);
}
